from typing import *
import json

class Solution:
    def solve(self, data: Dict[str, str]) -> bool:
        pattern = data['pattern']
        text = data['text']

        # Edge cases
        if not pattern and not text:
            return True
        elif not pattern:
            return False
        elif not text:
            return False

        # Brute-force approach
        def is_match(i, j):
            if i == len(pattern) and j == len(text):
                return True
            if i == len(pattern) or j == len(text):
                return False

            if pattern[i] == '?' or pattern[i] == text[j]:
                return is_match(i+1, j+1)

            if pattern[i] == '*':
                return is_match(i+1, j) or is_match(i, j+1)

            return False

        return is_match(0, 0)

