def solve(pattern, text):
    if len(pattern) == 0:
        return len(text) == 0
    if len(pattern) == 1:
        if pattern[0] == '*':
            return True
        elif pattern[0] == '?':
            return len(text) > 0
        else:
            return pattern[0] == text[0]
    if pattern[-1] == '*':
        return solve(pattern[:-1], text) or (len(text) > 0 and solve(pattern, text[1:]))
    else:
        return len(text) > 0 and pattern[0] == text[0] and solve(pattern[1:], text[1:])
